package cn.zhuatech.tax.controller; import cn.zhuatech.tax.common.ApiResponse; import cn.zhuatech.tax.dto.TaxDto.*; import cn.zhuatech.tax.service.TaxService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('TAX_ACCOUNTANT','ADMIN')") public class TaxAccountantController {private final TaxService service;public TaxAccountantController(TaxService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
